blocks.content:
1/* Resetting the Browser Styles */
2* {
3    margin: 0;
4    padding: 0;
5    box-sizing: border-box;
6    line-height: 1.5;
7}
8
9/* Container and Card Styles */
10.container {
11    display: flex;
12    justify-content: center;
13}
14
15.card {
16    display: flex;
17    border-radius: 24px;
18    background-color: white;
19    box-shadow: 0 10px 15px rgba(0, 0, 0, 0.1);
20    max-width: clamp(320px, 70vw, 740px);
21    min-width: min(320px, 100vw);
22    flex-direction: column;
23}
24
25/* Background and Image Styling */
26.background {
27    flex: 1 1 250px;
28    display: grid;
29    place-items: center;
30    background-color: #ebeffa;
31    border-radius: 24px 24px 0 0;
32}
33
34.background .image-wrapper {
35    display: flex;
36    width: 220px;
37    height: 220px;
38    border-radius: 50%;
39    overflow: hidden;
40    box-shadow: 0 8px 15px rgba(0, 0, 0, 0.15);
41    border: 1px solid white;
42}
43
44.background img {
45    max-width: 100%;
46    height: auto;
47    object-fit: cover;
48}
49
50/* Content Styling */
51.content {
52    flex: 3 1 350px;
53    display: flex;
54    flex-direction: column;
55    padding: 20px;
56    text-align: center;
57}
58
59.content h2 {
60    font-size: clamp(1rem, 1vw, 1.5rem);
61    font-weight: 700;
62    margin-bottom: clamp(0.35rem, 2vh, 0.55rem);
63    color: #29283f;
64}
65
66.content>p {
67    font-size: clamp(1rem, 1.7vw, 1.1rem);
68    font-weight: 500;
69    margin: 6px 0;
70}
71
72.content a {
73    text-decoration: none;
74    color: #7370f4;
75    font-weight: 600;
76}
77
78/* Chips and Buttons */
79.chips {
80    display: flex;
81    list-style-type: none;
82    padding: 12px 0;
83    justify-content: space-around;
84}
85
86.chip {
87    border-radius: 12px;
88    padding: 10px;
89    font-size: 15px;
90    background-color: #eaeaec;
91    font-weight: 600;
92    transition: all 0.3s ease-in-out;
93}
94
95.chip:hover {
96    background-color: #7370f4;
97    color: white;
98    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
99}
100
101.action-button {
102    border-top: 1px solid #eaeaec;
103    padding-top: 16px;
104    gap: 12px;
105    display: flex;
106    flex-direction: column;
107}
108
109.action-button a {
110    background-color: #29283f;
111    color: white;
112    padding: 12px;
113    text-decoration: none;
114    border-radius: 12px;
115    font-size: 18px;
116    display: flex;
117    justify-content: center;
118    align-items: center;
119    transition: transform 0.2s ease-in-out;
120}
121
122.action-button a:hover {
123    transform: scale(1.05);
124}
125
126.action-button a.secondary {
127    background-color: inherit;
128    color: #29283f;
129    border: 1px solid #29283f;
130}
